-- seed-datos.sql: datos de prueba referenciados para commerce-app (v3)
-- Requisito: backend levantado al menos una vez (Liquibase crea las tablas). Incluye el catalogo.
-- Ejecutar con psql (usa variables de psql). Se puede ejecutar varias veces.
\set ON_ERROR_STOP on
SET client_encoding = 'UTF8';
BEGIN;
-- Limpieza de una carga anterior (filas de este script: created_by = 'seed' y lo que cuelga de sus clientes)
CREATE TEMP TABLE tmp_cli ON COMMIT DROP AS SELECT id FROM cliente WHERE created_by = 'seed';
CREATE TEMP TABLE tmp_ped ON COMMIT DROP AS SELECT id FROM pedido WHERE cliente_id IN (SELECT id FROM tmp_cli);
DELETE FROM resena WHERE cliente_id IN (SELECT id FROM tmp_cli) OR created_by = 'seed';
UPDATE comprobante SET comprobante_referencia_id = NULL WHERE pedido_id IN (SELECT id FROM tmp_ped);
DELETE FROM comprobante WHERE pedido_id IN (SELECT id FROM tmp_ped);
DELETE FROM envio WHERE pedido_id IN (SELECT id FROM tmp_ped);
DELETE FROM pago WHERE pedido_id IN (SELECT id FROM tmp_ped);
DELETE FROM pedido_estado_historial WHERE pedido_id IN (SELECT id FROM tmp_ped);
DELETE FROM pedido_detalle WHERE pedido_id IN (SELECT id FROM tmp_ped);
DELETE FROM pedido WHERE id IN (SELECT id FROM tmp_ped);
DELETE FROM carrito_item WHERE carrito_id IN (SELECT id FROM carrito WHERE cliente_id IN (SELECT id FROM tmp_cli));
DELETE FROM carrito WHERE created_by = 'seed';
DELETE FROM cupon WHERE created_by = 'seed';
DELETE FROM inventario WHERE created_by = 'seed';
DELETE FROM dato_facturacion WHERE created_by = 'seed';
DELETE FROM direccion WHERE created_by = 'seed';
DELETE FROM cliente WHERE created_by = 'seed';
DELETE FROM empleado WHERE created_by = 'seed';
DELETE FROM medio_contacto WHERE created_by = 'seed';
DELETE FROM documento_identidad WHERE created_by = 'seed';
DELETE FROM persona WHERE created_by = 'seed';
DELETE FROM tienda WHERE created_by = 'seed';
DELETE FROM ubigeo WHERE created_by = 'seed';
DELETE FROM producto_imagen WHERE created_by = 'seed';
DELETE FROM producto p WHERE created_by = 'seed' AND NOT EXISTS (SELECT 1 FROM pedido_detalle d WHERE d.producto_id = p.id) AND NOT EXISTS (SELECT 1 FROM carrito_item c WHERE c.producto_id = p.id) AND NOT EXISTS (SELECT 1 FROM inventario i WHERE i.producto_id = p.id) AND NOT EXISTS (SELECT 1 FROM resena r WHERE r.producto_id = p.id) AND NOT EXISTS (SELECT 1 FROM producto_imagen m WHERE m.producto_id = p.id);
DELETE FROM marca m WHERE created_by = 'seed' AND NOT EXISTS (SELECT 1 FROM producto p WHERE p.marca_id = m.id);
DELETE FROM categoria c WHERE created_by = 'seed' AND NOT EXISTS (SELECT 1 FROM producto p WHERE p.categoria_id = c.id) AND NOT EXISTS (SELECT 1 FROM categoria h WHERE h.padre_id = c.id);
DELETE FROM categoria c WHERE created_by = 'seed' AND NOT EXISTS (SELECT 1 FROM producto p WHERE p.categoria_id = c.id) AND NOT EXISTS (SELECT 1 FROM categoria h WHERE h.padre_id = c.id);
DELETE FROM jhi_user_authority WHERE user_id IN (SELECT id FROM jhi_user WHERE created_by = 'seed' AND login NOT IN ('admin','user'));
DELETE FROM jhi_user WHERE created_by = 'seed' AND login NOT IN ('admin','user');
-- Rango de IDs propio, por encima de lo que ya reservo la aplicacion (secuencia de Hibernate, bloques de 50)
SELECT last_value + 1000 AS b FROM sequence_generator \gset
SELECT setval('sequence_generator', :b + 100000);
