CREATE TEMP TABLE tmp_prod ON COMMIT DROP AS SELECT (row_number() OVER (ORDER BY id)) - 1 AS n, p.* FROM producto p WHERE p.activo;
SELECT count(*) AS np FROM tmp_prod \gset
DO $$ BEGIN
  IF (SELECT count(*) FROM tmp_prod) < 5 THEN RAISE EXCEPTION 'No hay productos activos suficientes'; END IF;
END $$;
-- Detalle: copia el producto con su precio vigente (oferta si existe)
-- Totales del pedido (precios incluyen IGV 18%)
UPDATE pedido p SET subtotal = d.s FROM (SELECT pedido_id, sum(subtotal) s FROM pedido_detalle GROUP BY pedido_id) d WHERE d.pedido_id = p.id AND p.id BETWEEN (:b+2000) AND (:b+2199);
UPDATE pedido p SET descuento = CASE WHEN c.tipo_descuento = 'PORCENTAJE' THEN round(p.subtotal * c.valor / 100, 2) ELSE least(c.valor, p.subtotal) END FROM cupon c WHERE p.cupon_id = c.id AND p.subtotal >= COALESCE(c.monto_minimo, 0) AND p.id BETWEEN (:b+2000) AND (:b+2199);
UPDATE pedido SET cupon_id = NULL WHERE cupon_id IS NOT NULL AND descuento = 0 AND id BETWEEN (:b+2000) AND (:b+2199);
UPDATE pedido SET costo_envio = CASE WHEN tipo_entrega = 'DELIVERY' AND subtotal - descuento < 299 THEN 15 ELSE 0 END WHERE id BETWEEN (:b+2000) AND (:b+2199);
UPDATE pedido SET total = subtotal - descuento + costo_envio WHERE id BETWEEN (:b+2000) AND (:b+2199);
UPDATE pedido SET igv = round(total * 18 / 118, 2) WHERE id BETWEEN (:b+2000) AND (:b+2199);
UPDATE pago g SET monto = p.total FROM pedido p WHERE g.pedido_id = p.id AND p.id BETWEEN (:b+2000) AND (:b+2199);
UPDATE comprobante c SET total = p.total, igv = p.igv, op_gravada = p.total - p.igv FROM pedido p WHERE c.pedido_id = p.id AND p.id BETWEEN (:b+2000) AND (:b+2199);
-- Resenas sobre productos comprados (compra verificada)
-- Resenas sin compra verificada (pendientes de aprobacion)
-- Inventario: cada producto en cada tienda (el stock lo alimentaria el servicio de logistica)
-- Stock reservado por los pedidos PENDIENTE_PAGO vigentes
UPDATE inventario i SET stock_reservado = i.stock_reservado + d.cantidad, stock = greatest(i.stock, i.stock_reservado + d.cantidad) FROM pedido_detalle d WHERE d.pedido_id = (:b+2086) AND i.producto_id = d.producto_id AND i.tienda_id = (:b+101);
UPDATE inventario i SET stock_reservado = i.stock_reservado + d.cantidad, stock = greatest(i.stock, i.stock_reservado + d.cantidad) FROM pedido_detalle d WHERE d.pedido_id = (:b+2087) AND i.producto_id = d.producto_id AND i.tienda_id = (:b+104);
UPDATE inventario i SET stock_reservado = i.stock_reservado + d.cantidad, stock = greatest(i.stock, i.stock_reservado + d.cantidad) FROM pedido_detalle d WHERE d.pedido_id = (:b+2088) AND i.producto_id = d.producto_id AND i.tienda_id = (:b+100);
COMMIT;
SELECT (SELECT count(*) FROM cliente) AS clientes, (SELECT count(*) FROM empleado) AS empleados, (SELECT count(*) FROM producto) AS productos, (SELECT count(*) FROM inventario) AS inventario, (SELECT count(*) FROM pedido) AS pedidos, (SELECT count(*) FROM pedido_detalle) AS detalles, (SELECT count(*) FROM pago) AS pagos, (SELECT count(*) FROM comprobante) AS comprobantes, (SELECT count(*) FROM envio) AS envios, (SELECT count(*) FROM resena) AS resenas;
